def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n == 98:
        recent = history[-15:]
        recent_opp_coop = sum(1 for a, b in recent if b == 'C') / 15.0
        return 'D' if recent_opp_coop < 0.95 else 'C'
    if n >= 2 and history[-1][0] == 'D' and history[-1][1] == 'D' and history[-2][0] == 'D' and history[-2][1] == 'D':
        return 'C'
    my_last, opp_last = history[-1]
    if n < 10:
        return 'C' if opp_last == 'C' else 'D'
    opp_defections = sum(1 for a, b in history if b == 'D')
    opp_coop_rate = (n - opp_defections) / n
    if n < 30:
        if opp_coop_rate > 0.7:
            return 'C'
        if opp_coop_rate < 0.3:
            return 'D'
        return 'C' if opp_last == 'C' else 'D'
    recent = history[-15:]
    recent_opp_coop = sum(1 for a, b in recent if b == 'C') / 15.0
    recent_my_coop = sum(1 for a, b in recent if a == 'C') / 15.0
    if recent_opp_coop < 0.25:
        return 'D'
    if opp_coop_rate > 0.85 and recent_opp_coop > 0.85:
        return 'C'
    if opp_last == 'D':
        recent_defections = sum(1 for a, b in history[-5:] if b == 'D')
        if recent_defections >= 2:
            return 'D'
        if n >= 95:
            return 'D'
        return 'D' if rng.random() < 0.85 else 'C'
    if recent_opp_coop < 0.5:
        return 'D' if rng.random() < 0.5 else 'C'
    if n >= 95:
        return 'D' if recent_opp_coop < 0.9 else 'C'
    return 'C'
